steps.text:
/*
	VIOC_para_join.sqf - agregado por tools/vio_build.py (parche para_join; copia configurada, no es del autor de la mision).
	Fuente: work/v6_build/para_join/.

	Cliente de "saltar con los paracaidistas" (servidor en VIOC_specops.sqf, bloque "VIOC para_join"):
	  - VIOC_PJ_fnc_board (lo manda el servidor): guarda tu equipo (VIOC_PJ_SAVED, una vez), te pone el de un paracaidista
	    del equipo (sus armas, ropa y cargadores) con TUS objetos (mapa, GPS/terminal, radio, brujula, reloj; tus gafas de
	    vision nocturna si el no lleva) y un paracaidas dirigible a la espalda, y te sube al transporte (moveInCargo).
	  - Saltas con el primero del equipo (VIOC_PJ_fnc_jump). Si el aparato es ALCANZADO no se te obliga: aviso "El avion
	    fue alcanzado! Salta ahora" y decides tu (rueda: Saltar/Eject). Si lo DERRIBAN contigo dentro, vives o mueres como
	    diga el motor (sin proteccion ni salto automatico) y, si mueres, reapareces como cualquier muerte.
	  - En la caida: "Pulsa ESPACIO (o la rueda: Abrir paracaidas)"; si no lo abres, se abre solo a 160 m sobre el suelo
	    (Steerable_Parachute_F o el del paquete, como hacen las funciones de BIS: createVehicle + moveInDriver). No eres
	    invulnerable: solo se filtra el dano de CAIDA/CHOQUE (HandleDamage sin proyectil, VIOC_PJ_fnc_guard); balas,
	    metralla y explosiones te hacen dano normal en caida libre y bajo el paracaidas. Al tocar tierra recibes la mochila
	    del paracaidista (con su contenido).
	  - Oferta de los saltos de la IA (VIOC_PJ_fnc_offer): accion "UNIRSE AL SALTO" durante 60 s.
	  - Accion "Recuperar mi equipo anterior": donde puedes abrir MENU: Equipment (cuartel, camion de municion, FOB,
	    campamento/deposito), a menos de 200 m de tu HQ o de un pueblo tuyo (base avanzada). Gratis: es tu equipo.
	    Si mueres con el equipo de paracaidista, con "Start with last Gear" reapareces con el (es tu ultimo equipo) y
	    esta accion te sigue devolviendo el de antes del salto.
	Solo cliente (hasInterface). Parametro VIOC_PARA_JOIN (0 no, 1 solo mis pedidos, 2 + los de la IA cerca de mi base,
	3 + los de la IA desde cualquier lugar).
	Consola (Ejecucion local): VIOC_PJ_SAVED (equipo guardado), VIOC_PJ_RIDE (vuelo en curso), VIOC_PJ_OFFER (oferta)
*/
if (!hasInterface) exitWith {};
if ((missionNamespace getVariable ["VIOC_PARA_JOIN", 1]) <= 0) exitWith {};

VIOC_PJ_OPEN_AGL = 160;	//--- el paracaidas se abre solo por debajo de esta altura sobre el suelo (o el agua)

//--- Altura sobre el suelo o el agua.
VIOC_PJ_fnc_agl = {
	private _p = getPosASL player;
	if (surfaceIsWater _p) exitWith {_p select 2};
	(getPosATL player) select 2
};

//--- Filtro de dano SOLO de caida/choque (igual que VIOC_fnc_soFallGuard del servidor; HandleDamage solo dispara donde la
//--- unidad es local: el jugador, aqui). Sin proyectil ("") y origen nadie / tu / tu paracaidas / el aparato = sin dano
//--- (se devuelve el que ya tenias); con proyectil (balas, metralla, explosiones) no se devuelve nada: dano normal.
VIOC_PJ_fnc_guard = {
	params ["_u", ["_air", objNull], ["_secs", 300]];
	if (isNull _u || {!local _u}) exitWith {};
	_u setVariable ["vioc_fg_until", time + _secs];
	_u setVariable ["vioc_fg_air", _air];
	if ((_u getVariable ["vioc_fg_eh", -1]) >= 0) exitWith {};
	private _id = _u addEventHandler ["HandleDamage", {
		params ["_unit", "", "", "_source", "_projectile", "_hitIndex", "", "_hitPoint"];
		if ((_projectile isEqualTo "") && {time < (_unit getVariable ["vioc_fg_until", 0])} && {(isNull _source) || {_source == _unit} || {_source == (vehicle _unit)} || {_source isKindOf "ParachuteBase"} || {_source == (_unit getVariable ["vioc_fg_air", objNull])}}) then {
			private _cur = damage _unit;
			if (_hitIndex >= 0 && {_hitPoint != ""}) then {
				private _h = _unit getHitPointDamage _hitPoint;
				if (!isNil "_h") then {_cur = _h};
			};
			_cur
		}
	}];
	_u setVariable ["vioc_fg_eh", _id];
};
//--- Quita el filtro (HandleDamage puesto al jugador seguiria tras reaparecer: se quita al aterrizar o al morir).
VIOC_PJ_fnc_guardOff = {
	params ["_u"];
	if (isNull _u) exitWith {};
	private _id = _u getVariable ["vioc_fg_eh", -1];
	if (_id >= 0) then {_u removeEventHandler ["HandleDamage", _id]; _u setVariable ["vioc_fg_eh", -1]};
	_u setVariable ["vioc_fg_until", 0];
};

//--- Mensaje del servidor (si el cliente de PEDIR no esta, aqui).
VIOC_PJ_fnc_msg = {
	params ["_t"];
	hint _t;
	systemChat format ["[Paracaidistas] %1", _t];
};

//--- Subir al transporte con equipo de paracaidista (lo manda el servidor, VIOC_fnc_pjSend).
VIOC_PJ_fnc_board = {
	params ["_veh", "_lo", "_chute", "_label"];
	[_veh, _lo, _chute, _label] spawn {
		params ["_veh", "_lo", "_chute", "_label"];
		if (!alive player || {isNull _veh} || {!alive _veh}) exitWith {};
		if (!isNil "VIOC_PJ_RIDE") exitWith {["Ya vas en un salto."] call VIOC_PJ_fnc_msg};
		VIOC_PJ_RIDE = [_veh];
		private _old = getUnitLoadout player;
		private _saved = isNil "VIOC_PJ_SAVED";
		if (_saved) then {VIOC_PJ_SAVED = _old};
		//--- el equipo de un soldado del equipo, con tus objetos y el paracaidas a la espalda
		private _new = if (_lo isEqualType [] && {count _lo >= 10}) then {+_lo} else {+_old};
		private _tbp = +(_new param [5, []]);
		private _ai = +(_new param [9, []]);
		private _mine = _old param [9, []];
		if (count _ai < 6) then {_ai resize 6; _ai = _ai apply {if (isNil "_x") then {""} else {_x}}};
		{if ((_mine param [_x, ""]) isEqualType "" && {(_mine param [_x, ""]) != ""}) then {_ai set [_x, _mine select _x]}} forEach [0, 1, 2, 3, 4];
		if ((_ai param [5, ""]) isEqualTo "") then {_ai set [5, _mine param [5, ""]]};
		_new set [9, _ai];
		_new set [5, [_chute param [0, "B_Parachute"], []]];
		if (vehicle player != player) then {moveOut player; sleep 0.3};
		player setUnitLoadout _new;
		player moveInCargo _veh;
		sleep 0.5;
		if (vehicle player != _veh && {alive _veh}) then {player moveInCargo _veh; sleep 0.5};
		if (vehicle player != _veh) exitWith {
			player setUnitLoadout _old;
			if (_saved) then {VIOC_PJ_SAVED = nil};
			VIOC_PJ_RIDE = nil;
			["No pudiste subir al transporte (sin sitio o ya no esta). Tu equipo no cambio."] call VIOC_PJ_fnc_msg;
		};
		hint parseText format ["<t size='1.1' color='#ffb27f'>Salto de paracaidistas</t><br/><br/><t align='left'>Vas en el transporte de %1, con equipo de paracaidista (tu equipo de antes esta guardado: accion 'Recuperar mi equipo anterior' en la base).<br/><br/>Saltas con el equipo sobre la zona de salto. En la caida: <t color='#76F563'>Pulsa ESPACIO para abrir el paracaidas</t> (o la rueda del raton: Abrir paracaidas). Si no lo abres, se abre solo a %2 m.</t>", _label, VIOC_PJ_OPEN_AGL];
		//--- mientras vas dentro: si el aparato es alcanzado y aun vuela alto, se te avisa (no se te saca): decides tu
		private _warned = false;
		waitUntil {
			sleep 0.25;
			if (!_warned && {vehicle player == _veh} && {alive _veh} && {(damage _veh > 0.3) || {!canMove _veh} || {!alive (driver _veh)}} && {(call VIOC_PJ_fnc_agl) > 60}) then {
				_warned = true;
				hint parseText "<t size='1.3' color='#F56363'>¡El avión fue alcanzado! Salta ahora</t><br/>(rueda: Saltar/Eject)";
			};
			(vehicle player != _veh) || {!alive player}
		};
		//--- si el aparato fue derribado (destruido), no hay ni salto ni proteccion: lo que diga el motor
		if (alive player && {alive _veh}) then {[_tbp, _chute param [1, "Steerable_Parachute_F"], _veh] call VIOC_PJ_fnc_fall};
		VIOC_PJ_RIDE = nil;
	};
};

//--- Salir por detras y debajo del aparato (como los paracaidistas IA), con el filtro de dano de caida/choque.
VIOC_PJ_fnc_doJump = {
	params ["_veh"];
	if (vehicle player != _veh) exitWith {};
	private _back = ((sizeOf (typeOf _veh)) * 0.45) max 8;
	private _p = _veh modelToWorldWorld [0, -_back, -4];
	[player, _veh, 300] call VIOC_PJ_fnc_guard;
	moveOut player;
	player setPosASL _p;
	player setVelocity ((velocity _veh) vectorMultiply 0.3);
};

//--- Orden del servidor: saltar con el equipo (o bajar si el aparato esta en tierra).
VIOC_PJ_fnc_jump = {
	params ["_veh"];
	if (isNull _veh || {vehicle player != _veh}) exitWith {};
	[_veh] spawn {
		params ["_veh"];
		private _t = time + 120;
		waitUntil {sleep 0.25; (vehicle player != _veh) || {!alive player} || {((getPosATL _veh) select 2) > 60} || {isTouchingGround _veh && {(speed _veh) < 3}} || {time > _t}};
		if (vehicle player != _veh || {!alive player}) exitWith {};
		if (isTouchingGround _veh && {(speed _veh) < 3}) then {moveOut player} else {[_veh] call VIOC_PJ_fnc_doJump};
	};
};

//--- Caida libre y paracaidas hasta el suelo. Solo se filtra el dano de caida/choque (VIOC_PJ_fnc_guard); el resto es normal.
VIOC_PJ_fnc_fall = {
	params ["_tbp", "_chuteCls", ["_air", objNull]];
	if ((call VIOC_PJ_fnc_agl) < 3 && {vehicle player == player}) exitWith {[_tbp] call VIOC_PJ_fnc_landed};
	[player, _air, 300] call VIOC_PJ_fnc_guard;
	if (vehicle player == player) then {hint parseText format ["<t size='1.2' color='#76F563'>Pulsa ESPACIO para abrir el paracaidas</t><br/>(o la rueda del raton: Abrir paracaidas). Si no lo abres, se abre solo a %1 m.", VIOC_PJ_OPEN_AGL]};
	private _opened = false;
	private _t = time + 300;
	waitUntil {
		sleep 0.1;
		private _v = vehicle player;
		if (_v != player && {_v isKindOf "ParachuteBase"}) then {
			_opened = true;
		} else {
			if (!_opened && {_v == player} && {(call VIOC_PJ_fnc_agl) < VIOC_PJ_OPEN_AGL} && {(call VIOC_PJ_fnc_agl) > 15}) then {
				//--- se abre solo (como BIS: crear el paracaidas en tu posicion y subirte de piloto, sin interrupciones)
				isNil {
					private _c = createVehicle [_chuteCls, getPosATL player, [], 0, "CAN_COLLIDE"];
					if (isNull _c) then {_c = createVehicle ["Steerable_Parachute_F", getPosATL player, [], 0, "CAN_COLLIDE"]};
					_c setPosASL (getPosASL player);
					_c setDir (getDir player);
					player moveInDriver _c;
					_c setVelocity [0, 0, -5];
				};
				_opened = true;
				private _bp = backpack player;
				if (_bp != "" && {getText (configFile >> "CfgVehicles" >> _bp >> "ParachuteClass") != ""}) then {removeBackpack player};
				hint "Paracaidas abierto automaticamente.";
			};
		};
		!alive player || {(vehicle player == player) && {isTouchingGround player || {(call VIOC_PJ_fnc_agl) < 0.5}}} || {time > _t}
	};
	//--- muerto en el aire: se quita el filtro ya (la muerte y la reaparicion siguen el flujo normal de la mision)
	if (!alive player) exitWith {[player] call VIOC_PJ_fnc_guardOff};
	sleep 2;
	[player] call VIOC_PJ_fnc_guardOff;
	if (alive player) then {[_tbp] call VIOC_PJ_fnc_landed};
};

//--- En tierra: la mochila del paracaidista (con su contenido) en lugar del paracaidas.
VIOC_PJ_fnc_landed = {
	params ["_tbp"];
	if !(_tbp isEqualType [] && {count _tbp > 0}) exitWith {};
	private _bp = backpack player;
	if (_bp == "" || {getText (configFile >> "CfgVehicles" >> _bp >> "ParachuteClass") != ""}) then {
		private _lo = getUnitLoadout player;
		_lo set [5, _tbp];
		player setUnitLoadout _lo;
	};
};

//--- Oferta de un salto de la IA (60 s): accion "UNIRSE AL SALTO".
VIOC_PJ_fnc_offer = {
	params ["_key", "_label", ["_secs", 60]];
	if (!isNil "VIOC_PJ_RIDE") exitWith {};
	VIOC_PJ_OFFER = [_key, time + _secs, _label];
	hint parseText format ["<t size='1.1' color='#ffb27f'>Salto de paracaidistas</t><br/><br/>%1 sale ahora. Si quieres saltar con ellos usa la accion <t color='#76F563'>UNIRSE AL SALTO</t> (%2 s, gratis).", _label, _secs];
	systemChat format ["[Paracaidistas] %1 sale ahora: accion UNIRSE AL SALTO (%2 s).", _label, _secs];
};
VIOC_PJ_fnc_offerOk = {
	!isNil "VIOC_PJ_OFFER" && {isNil "VIOC_PJ_RIDE"} && {time < (VIOC_PJ_OFFER select 1)}
};
VIOC_PJ_fnc_accept = {
	if !(call VIOC_PJ_fnc_offerOk) exitWith {};
	[player, VIOC_PJ_OFFER select 0] remoteExecCall ["VIOC_fnc_pjAccept", 2];
	VIOC_PJ_OFFER = nil;
	systemChat "[Paracaidistas] Pedido enviado: subes al transporte en un momento.";
};

//--- "Recuperar mi equipo anterior": en la base, FOB, camion de municion, campamento, o a 200 m de tu HQ o de un pueblo tuyo.
VIOC_PJ_fnc_canRestore = {
	if (isNil "VIOC_PJ_SAVED" || {vehicle player != player}) exitWith {false};
	if ((missionNamespace getVariable ["CTI_Base_GearInRange", false]) || {missionNamespace getVariable ["CTI_Base_GearInRange_Mobile", false]} || {missionNamespace getVariable ["CTI_Base_GearInRange_FOB", false]} || {missionNamespace getVariable ["CTI_Town_GearInRange", false]}) exitWith {true};
	private _hq = CTI_P_SideJoined call CTI_CO_FNC_GetSideHQ;
	if (!isNil "_hq" && {_hq isEqualType objNull} && {!isNull _hq} && {(_hq distance2D player) < 200}) exitWith {true};
	private _sid = CTI_P_SideJoined call CTI_CO_FNC_GetSideID;
	((missionNamespace getVariable ["CTI_Towns", []]) findIf {((_x getVariable ["cti_town_sideID", -1]) == _sid) && {(_x distance2D player) < 200}}) >= 0
};
VIOC_PJ_fnc_restore = {
	if !(call VIOC_PJ_fnc_canRestore) exitWith {hint "Recupera tu equipo en la base, un FOB, un camion de municion o un pueblo tuyo."};
	player setUnitLoadout VIOC_PJ_SAVED;
	VIOC_PJ_SAVED = nil;
	hint "Recuperaste el equipo que tenias antes del salto.";
};

