[_veh, _cg, _op] spawn {params ["_veh", "_cg", "_op"]; [_veh, _op] call VIOC_fnc_pjEnd; [_veh] call VIOC_fnc_pjSafeDelete; {deleteVehicle _x} forEach (units _cg)};

