steps.text:
//--- VIOC para_join: saltar con ellos = solo paracaidistas, y se comprueba ANTES de cobrar que puedes subir
if (_jump) then {_want = "para"};
private _pjWhy = if (_jump) then {[_player] call VIOC_fnc_pjCheck} else {""};
if (_pjWhy != "") exitWith {format ["no puedes saltar con ellos: %1", _pjWhy]};

//=====================================================================================================================
//--- VIOC para_join: el JUGADOR salta con los paracaidistas (parametro VIOC_PARA_JOIN; cliente en VIOC_para_join.sqf).
//---   - En su propio pedido de paracaidistas ("Saltar con ellos (yo tambien)" en el panel PEDIR): se valida ANTES de
//---     cobrar que puede subir (vivo, consciente, a pie o de pasajero en un vehiculo de tierra parado) y se le reserva un
//---     asiento; cuando el avion sale (VIOC_fnc_soDoPara), el servidor le manda subir (VIOC_PJ_fnc_board en SU maquina:
//---     moveInCargo es local al jugador) con el equipo de un soldado normal del equipo (no el jefe ni el medico) y un
//---     paracaidas dirigible.
//---   - En las operaciones de paracaidistas de la IA de su bando (VIOC_PARA_JOIN 2 = si esta a menos de 500 m de la base
//---     de salida, 3 = desde cualquier lugar): oferta "UNIRSE AL SALTO" de 60 s (gratis), validada otra vez aqui.
//---   - Salta con el primero del equipo (VIOC_fnc_pjJump). Si la operacion se cancela sin combate o el aparato se va a
//---     borrar, el jugador sale antes (VIOC_fnc_pjSafeDelete nunca borra un aparato con un jugador dentro). Si el aparato es
//---     alcanzado NO se le obliga ni protege: se le avisa y decide; si lo derriban, vive o muere como diga el motor.
//---   - Nadie es invulnerable: quien salta (jugador o IA) solo lleva un filtro de dano de caida/choque (VIOC_fnc_soFallGuard).
//---   - El jugador no cuenta para ningun tope de las operaciones especiales ni cambia nada para las demas.
//=====================================================================================================================
VIOC_PJ_MODE = missionNamespace getVariable ["VIOC_PARA_JOIN", 1];
if !(VIOC_PJ_MODE isEqualType 0) then {VIOC_PJ_MODE = 1};
VIOC_PJ_OPS = createHashMap;	//--- ofertas de saltos de la IA: str token -> [operacion, aparato, fin de la oferta]
VIOC_PJ_NEAR = 500;				//--- con VIOC_PARA_JOIN = 2, distancia maxima a la base de salida

//--- Filtro de dano SOLO de caida/choque para quien salta o desembarca (en lugar de allowDamage false): mientras dure la
//--- ventana, un golpe sin proyectil ("" = caida, choque) cuyo origen es nadie, la unidad, su paracaidas o el aparato no
//--- hace dano (se devuelve el dano que ya tenia esa parte); balas, metralla y explosiones (proyectil != "") hacen su
//--- dano normal en caida libre y bajo el paracaidas. HandleDamage solo dispara donde la unidad es local (aqui: la IA
//--- del servidor). Parametros de HandleDamage en 2.22: unit, selection, damage, source, projectile, hitPartIndex,
//--- instigator, hitPoint, directHit, context. Si no devuelve nada, el motor hace lo de siempre.
VIOC_fnc_soFallGuard = {
	params ["_u", ["_air", objNull], ["_secs", 240]];
	if (isNull _u || {!local _u}) exitWith {};
	_u setVariable ["vioc_fg_until", time + _secs];
	_u setVariable ["vioc_fg_air", _air];
	if ((_u getVariable ["vioc_fg_eh", -1]) >= 0) exitWith {};
	private _id = _u addEventHandler ["HandleDamage", {
		params ["_unit", "", "", "_source", "_projectile", "_hitIndex", "", "_hitPoint"];
		if ((_projectile isEqualTo "") && {time < (_unit getVariable ["vioc_fg_until", 0])} && {(isNull _source) || {_source == _unit} || {_source == (vehicle _unit)} || {_source isKindOf "ParachuteBase"} || {_source == (_unit getVariable ["vioc_fg_air", objNull])}}) then {
			private _cur = damage _unit;
			if (_hitIndex >= 0 && {_hitPoint != ""}) then {
				private _h = _unit getHitPointDamage _hitPoint;
				if (!isNil "_h") then {_cur = _h};
			};
			_cur
		}
	}];
	_u setVariable ["vioc_fg_eh", _id];
};
VIOC_fnc_soFallGuardOff = {
	params ["_u"];
	if (isNull _u) exitWith {};
	private _id = _u getVariable ["vioc_fg_eh", -1];
	if (_id >= 0) then {_u removeEventHandler ["HandleDamage", _id]; _u setVariable ["vioc_fg_eh", -1]};
	_u setVariable ["vioc_fg_until", 0];
};

//--- "" si el jugador puede subir al transporte, si no el motivo.
VIOC_fnc_pjCheck = {
	params ["_p"];
	if (VIOC_PJ_MODE <= 0) exitWith {"saltar con los paracaidistas esta desactivado en el lobby"};
	if (!alive _p || {lifeState _p == "INCAPACITATED"}) exitWith {"tienes que estar vivo y consciente"};
	private _v = vehicle _p;
	if (_v != _p && {(driver _v == _p) || {_v isKindOf "Air"} || {(speed _v) > 5} || {!isTouchingGround _v}}) exitWith {"bajate del vehiculo (o deja de conducirlo) para saltar con ellos"};
	""
};

//--- Equipo de un soldado normal del equipo (no el jefe, ni un medico; mejor sin lanzador), como se creo.
VIOC_fnc_pjTemplate = {
	params ["_team"];
	private _all = (units _team) select {alive _x};
	private _l = leader _team;
	private _c = _all select {(_x != _l) && {getNumber (configFile >> "CfgVehicles" >> (typeOf _x) >> "attendant") == 0}};
	private _r = _c select {secondaryWeapon _x == ""};
	private _u = objNull;
	if (count _r > 0) then {_u = selectRandom _r} else {if (count _c > 0) then {_u = selectRandom _c} else {if (count _all > 0) then {_u = _all select 0}}};
	if (isNull _u) exitWith {[]};
	getUnitLoadout _u
};

//--- Paracaidas del jugador: [mochila, paracaidas] = la mochila del paracaidas del paquete si es dirigible
//--- (CUP_T10_Parachute_backpack, rhs_d6_Parachute_backpack...), si no B_Parachute / Steerable_Parachute_F.
VIOC_fnc_pjChute = {
	params ["_op"];
	private _res = ["B_Parachute", "Steerable_Parachute_F"];
	private _ch = _op getOrDefault ["chute", ""];
	if (_ch isEqualType "" && {_ch != ""}) then {
		private _cfg = configFile >> "CfgVehicles" >> (_ch + "_backpack");
		if (isClass _cfg && {getNumber (_cfg >> "isBackpack") == 1} && {getNumber (_cfg >> "scope") >= 1}) then {
			private _pc = getText (_cfg >> "ParachuteClass");
			if (_pc != "" && {_pc isKindOf "Paraglide"}) then {_res = [configName _cfg, _pc]};
		};
	};
	_res
};

//--- Manda subir a un jugador (se corre en su maquina). Devuelve true si se le mando.
VIOC_fnc_pjSend = {
	params ["_op", "_veh", "_p"];
	private _why = [_p] call VIOC_fnc_pjCheck;
	if (_why == "" && {(side group _p) != (_op get "side")}) then {_why = "no es una operacion de tu bando"};
	if (_why == "" && {!alive _veh || {!canMove _veh}}) then {_why = "el transporte ya no esta"};
	if (_why == "" && {vehicle _p == _veh}) then {_why = "ya vas en el transporte"};
	if (_why == "" && {(_veh emptyPositions "Cargo") < 1}) then {_why = "no queda sitio en el transporte"};
	if (_why != "") exitWith {[format ["No puedes saltar con ellos: %1.", _why]] remoteExecCall ["VIOC_PJ_fnc_msg", _p]; false};
	if (count (_op getOrDefault ["pjlo", []]) == 0) then {_op set ["pjlo", getUnitLoadout _p]};
	[_veh, _op get "pjlo", _op getOrDefault ["pjchute", ["B_Parachute", "Steerable_Parachute_F"]], (_op get "pkg") get "name"] remoteExecCall ["VIOC_PJ_fnc_board", _p];
	format ["%1 sube al transporte de %2", name _p, (_op get "pkg") get "id"] call VIOC_fnc_soLog;
	true
};

//--- Lo llama VIOC_fnc_soDoPara con el equipo ya a bordo: sube a quien lo pidio y ofrece el salto de la IA.
VIOC_fnc_pjBoard = {
	params ["_op", "_veh", "_team"];
	if (VIOC_PJ_MODE <= 0) exitWith {};
	_op set ["pjlo", [_team] call VIOC_fnc_pjTemplate];
	_op set ["pjchute", [_op] call VIOC_fnc_pjChute];
	{[_op, _veh, _x] call VIOC_fnc_pjSend} forEach ((_op getOrDefault ["pj", []]) select {!isNull _x});
	if ((_op getOrDefault ["preq", ""]) isEqualTo "" && {VIOC_PJ_MODE >= 2}) then {
		private _key = str (_op get "tok");
		VIOC_PJ_OPS set [_key, [_op, _veh, time + 60]];
		private _side = _op get "side";
		private _home = _op getOrDefault ["home", []];
		private _pl = allPlayers - (entities "HeadlessClient_F");
		if (!isMultiplayer && {hasInterface} && {!isNull player}) then {_pl pushBackUnique player};
		_pl = _pl select {alive _x && {(side group _x) == _side} && {(VIOC_PJ_MODE >= 3) || {(count _home > 0) && {(_x distance2D _home) < VIOC_PJ_NEAR}}}};
		private _label = format ["%1 hacia %2", (_op get "pkg") get "name", (_op get "town") getVariable ["cti_town_name", "el objetivo"]];
		{[_key, _label, 60] remoteExecCall ["VIOC_PJ_fnc_offer", _x]} forEach _pl;
	};
};

//--- "UNIRSE AL SALTO" (remoteExecCall desde el cliente): se valida otra vez y se manda subir (gratis).
VIOC_fnc_pjAccept = {
	params [["_p", objNull, [objNull]], ["_key", "", [""]]];
	if (!isServer || {isNull _p}) exitWith {};
	private _ro = remoteExecutedOwner;
	if (isMultiplayer && {_ro > 0} && {_ro != (owner _p)}) exitWith {};
	private _e = VIOC_PJ_OPS getOrDefault [_key, []];
	if (count _e < 3 || {time > (_e select 2)}) exitWith {["Ese salto ya no esta disponible (ya saltaron o paso el tiempo)."] remoteExecCall ["VIOC_PJ_fnc_msg", _p]};
	_e params ["_op", "_veh"];
	private _home = _op getOrDefault ["home", []];
	if (VIOC_PJ_MODE < 3 && {(count _home == 0) || {(_p distance2D _home) > (VIOC_PJ_NEAR + 100)}}) exitWith {[format ["Para unirte al salto tienes que estar a menos de %1 m de tu base.", VIOC_PJ_NEAR]] remoteExecCall ["VIOC_PJ_fnc_msg", _p]};
	[_op, _veh, _p] call VIOC_fnc_pjSend;
};

//--- Los jugadores que van en el aparato saltan (o bajan, si esta en tierra) en su maquina.
VIOC_fnc_pjJump = {
	params ["_veh"];
	if (isNull _veh) exitWith {};
	{if (isPlayer _x) then {[_veh] remoteExecCall ["VIOC_PJ_fnc_jump", _x]}} forEach (crew _veh);
};

//--- Fin del vuelo de ida: cierra la oferta y (_force) que no quede ningun jugador dentro. Si el aparato fue alcanzado
//--- (_force = false) no se obliga a nadie: el jugador decide si salta (su cliente le avisa).
VIOC_fnc_pjEnd = {
	params ["_veh", "_op", ["_force", true]];
	private _e = VIOC_PJ_OPS getOrDefault [str (_op get "tok"), []];
	if (count _e > 2) then {_e set [2, -1]};
	if (_force) then {[_veh] call VIOC_fnc_pjJump};
};

//--- Borra el aparato y su tripulacion IA, pero nunca con un jugador dentro (antes le hace saltar o bajar; espera 90 s).
VIOC_fnc_pjSafeDelete = {
	params ["_veh"];
	if (isNull _veh) exitWith {};
	if (({isPlayer _x} count (crew _veh)) > 0) then {
		[_veh] call VIOC_fnc_pjJump;
		private _t = time + 90;
		waitUntil {sleep 1; isNull _veh || {({isPlayer _x} count (crew _veh)) == 0} || {time > _t}};
	};
	if (isNull _veh) exitWith {};
	if (({isPlayer _x} count (crew _veh)) > 0) exitWith {"para_join: queda un jugador dentro, el aparato no se borra" call VIOC_fnc_soLog};
	{deleteVehicle _x} forEach (crew _veh);
	deleteVehicle _veh;
};

